fn solve(s: Vec<char>) -> Vec<char> {
    // Pre–allocate exactly one more than the input length
    let mut result = Vec::with_capacity(s.len() + 1);
    // Replace commas with spaces and otherwise copy the character
    for c in s {
        result.push(if c == ',' { ' ' } else { c });
    }
    // Append the newline
    result.push('\n');
    result
}

